insert_rust=r'''#[derive(Debug,Clone,Serialize,Deserialize,Default)]
struct GoogleConfig{#[serde(default)] client_id:String,#[serde(default)] client_secret:String,#[serde(default)] project_id:String,#[serde(default)] api_key:String}
fn google_config_path(app:&AppHandle)->Result<PathBuf,String>{let dir=app.path().app_data_dir().map_err(|e|e.to_string())?;fs::create_dir_all(&dir).map_err(|e|e.to_string())?;Ok(dir.join("google-config.json"))}
fn load_google_config(app:&AppHandle)->Result<GoogleConfig,String>{let p=google_config_path(app)?;if !p.exists(){return Ok(GoogleConfig::default())}let b=fs::read(&p).map_err(|e|format!("Google config read: {e}"))?;serde_json::from_slice(&b).map_err(|e|format!("Google config parse: {e}"))}
fn save_google_config(app:&AppHandle,c:&GoogleConfig)->Result<(),String>{let p=google_config_path(app)?;let tmp=p.with_extension("tmp");let b=serde_json::to_vec_pretty(c).map_err(|e|e.to_string())?;fs::write(&tmp,b).map_err(|e|format!("Google config write: {e}"))?;fs::rename(&tmp,&p).map_err(|e|format!("Google config replace: {e}"))?;#[cfg(unix)]{use std::os::unix::fs::PermissionsExt;let _=fs::set_permissions(&p,fs::Permissions::from_mode(0o600));}Ok(())}
fn masked_client_id(s:&str)->String{if s.len()>16{format!("{}…{}",&s[..8],&s[s.len()-8..])}else if s.is_empty(){String::new()}else{"configured".into()}}
fn google_config_status_value(c:&GoogleConfig)->Value{json!({"configured":!c.client_id.trim().is_empty(),"projectId":if c.project_id.is_empty(){Value::Null}else{json!(c.project_id)},"clientIdMasked":if c.client_id.is_empty(){Value::Null}else{json!(masked_client_id(&c.client_id))},"hasSecret":!c.client_secret.is_empty(),"hasApiKey":!c.api_key.is_empty()})}
#[tauri::command]
pub fn youtube_google_config_status(app:AppHandle)->Result<Value,String>{Ok(google_config_status_value(&load_google_config(&app)?))}
#[tauri::command]
pub fn youtube_google_config_import(app:AppHandle,json_text:String,api_key:String)->Result<Value,String>{let v:Value=serde_json::from_str(&json_text).map_err(|e|format!("credentials.json: {e}"))?;let root=v.get("installed").or_else(||v.get("web")).unwrap_or(&v);let client_id=root.get("client_id").and_then(|x|x.as_str()).unwrap_or("").trim().to_string();if client_id.is_empty(){return Err("В credentials.json не найден client_id".into())}let client_secret=root.get("client_secret").and_then(|x|x.as_str()).unwrap_or("").trim().to_string();let project_id=root.get("project_id").and_then(|x|x.as_str()).or_else(||v.get("project_id").and_then(|x|x.as_str())).unwrap_or("").trim().to_string();let old=load_google_config(&app).unwrap_or_default();let c=GoogleConfig{client_id,client_secret,project_id,api_key:if api_key.trim().is_empty(){old.api_key}else{api_key.trim().to_string()}};save_google_config(&app,&c)?;Ok(google_config_status_value(&c))}
#[tauri::command]
pub async fn youtube_oauth_connect_global(app:AppHandle)->Result<Value,String>{let c=load_google_config(&app)?;if c.client_id.trim().is_empty(){return Err("Сначала импортируй Google credentials.json в разделе Аккаунты".into())}youtube_oauth_connect(app,c.client_id,c.client_secret).await}
#[tauri::command]
pub async fn youtube_oauth_profile_health(app:AppHandle,profile_id:String)->Result<Value,String>{let (_token,p)=valid_access_token(&app,&profile_id).await?;let token=p.access_token.clone();let r=reqwest::Client::new().get("https://www.googleapis.com/youtube/v3/channels").bearer_auth(&token).query(&[("part","snippet"),("mine","true")]).send().await.map_err(|e|format!("YouTube health: {e}"))?;let st=r.status();let v:Value=r.json().await.unwrap_or_else(|_|json!({}));if !st.is_success(){return Err(youtube_error(&v,"YouTube OAuth health check failed"))}let item=v.get("items").and_then(|x|x.as_array()).and_then(|a|a.first()).cloned().unwrap_or_else(||json!({}));let sn=item.get("snippet").cloned().unwrap_or_else(||json!({}));let thumb=sn.pointer("/thumbnails/high/url").or_else(||sn.pointer("/thumbnails/medium/url")).or_else(||sn.pointer("/thumbnails/default/url")).and_then(|x|x.as_str());Ok(json!({"ok":true,"status":"TOKEN_HEALTHY","channelId":item.get("id").and_then(|x|x.as_str()).or(p.channel_id.as_deref()),"channelTitle":sn.get("title").and_then(|x|x.as_str()).or(p.channel_title.as_deref()),"thumbnail":thumb,"expiresAt":p.expires_at}))}
#[tauri::command]
pub async fn youtube_cache_thumbnail(app:AppHandle,video_id:String,primary:Option<String>)->Result<String,String>{let id=video_id.trim();if id.is_empty(){return Err("Video ID пуст".into())}let dir=app.path().app_cache_dir().map_err(|e|e.to_string())?.join("thumbnails");fs::create_dir_all(&dir).map_err(|e|format!("Thumbnail cache: {e}"))?;let safe=id.chars().filter(|c|c.is_ascii_alphanumeric()||*c=='_'||*c=='-').collect::<String>();let path=dir.join(format!("{safe}.jpg"));if path.exists()&&fs::metadata(&path).map(|m|m.len()>900).unwrap_or(false){return Ok(path.to_string_lossy().to_string())}let mut urls=Vec::<String>::new();if let Some(x)=primary.filter(|x|!x.trim().is_empty()){urls.push(x)}for q in ["maxresdefault","sddefault","hqdefault","mqdefault","default"]{urls.push(format!("https://i.ytimg.com/vi/{id}/{q}.jpg"))}let client=reqwest::Client::builder().timeout(Duration::from_secs(12)).build().map_err(|e|e.to_string())?;for url in urls{for attempt in 0..2{match client.get(&url).send().await{Ok(r) if r.status().is_success()=>{let b=r.bytes().await.map_err(|e|e.to_string())?;if b.len()>900{let tmp=path.with_extension("tmp");fs::write(&tmp,&b).map_err(|e|e.to_string())?;fs::rename(&tmp,&path).map_err(|e|e.to_string())?;return Ok(path.to_string_lossy().to_string())}},Ok(_)=>{},Err(_)=>{if attempt==0{tokio::time::sleep(Duration::from_millis(250)).await;}}}}Err("Thumbnail недоступна после fallback".into())}
'''
