discovery=r'''fn keywords(text:&str)->Vec<String>{let stop=["the","and","for","with","from","this","that","your","you","radio","music","mix","playlist","official","channel","video","songs","song","new","best","для","это","как","что","или","канал","музыка"];let mut counts=std::collections::HashMap::<String,u32>::new();for raw in text.split(|c:char|!c.is_alphanumeric()){let w=raw.to_lowercase();if w.chars().count()<3||stop.contains(&w.as_str()){continue}*counts.entry(w).or_insert(0)+=1}let mut v=counts.into_iter().collect::<Vec<_>>();v.sort_by(|a,b|b.1.cmp(&a.1).then(a.0.cmp(&b.0)));v.into_iter().take(8).map(|x|x.0).collect()}
fn overlap_score(own:&[String],text:&str)->u32{if own.is_empty(){return 0}let low=text.to_lowercase();let hit=own.iter().filter(|k|low.contains(k.as_str())).count() as f64;((hit/own.len() as f64)*100.0).round().clamp(0.0,100.0) as u32}
#[tauri::command]
pub async fn youtube_discover_competitors(app:AppHandle,profile_id:String,max_results:Option<u32>)->Result<Value,String>{let (token,_)=youtube::access_token_and_scopes(&app,&profile_id).await?;let client=reqwest::Client::new();let cr=client.get("https://www.googleapis.com/youtube/v3/channels").bearer_auth(&token).query(&[("part","snippet,contentDetails"),("mine","true")]).send().await.map_err(|e|format!("Own channel: {e}"))?;let cv:Value=cr.json().await.unwrap_or_else(|_|json!({}));let own=cv.get("items").and_then(|x|x.as_array()).and_then(|a|a.first()).ok_or_else(||"Собственный YouTube-канал не найден".to_string())?;let own_id=own.get("id").and_then(|x|x.as_str()).unwrap_or("");let mut corpus=String::new();corpus.push_str(own.pointer("/snippet/title").and_then(|x|x.as_str()).unwrap_or(""));corpus.push(' ');corpus.push_str(own.pointer("/snippet/description").and_then(|x|x.as_str()).unwrap_or(""));if let Some(uploads)=own.pointer("/contentDetails/relatedPlaylists/uploads").and_then(|x|x.as_str()){let pr=client.get("https://www.googleapis.com/youtube/v3/playlistItems").bearer_auth(&token).query(&[("part","snippet"),("playlistId",uploads),("maxResults","12")]).send().await.map_err(|e|format!("Own uploads: {e}"))?;let pv:Value=pr.json().await.unwrap_or_else(|_|json!({}));for x in pv.get("items").and_then(|x|x.as_array()).cloned().unwrap_or_default(){if let Some(t)=x.pointer("/snippet/title").and_then(|x|x.as_str()){corpus.push(' ');corpus.push_str(t)}}}let own_keys=keywords(&corpus);let query=own_keys.iter().take(6).cloned().collect::<Vec<_>>().join(" ");if query.is_empty(){return Err("Недостаточно данных канала для автоматического поиска конкурентов".into())}let max=max_results.unwrap_or(8).clamp(3,15);let max_s=max.to_string();let sr=client.get("https://www.googleapis.com/youtube/v3/search").bearer_auth(&token).query(&[("part","snippet"),("type","channel"),("q",query.as_str()),("maxResults",max_s.as_str())]).send().await.map_err(|e|format!("Competitor discovery: {e}"))?;let ss=sr.status();let sv:Value=sr.json().await.unwrap_or_else(|_|json!({}));if !ss.is_success(){return Err(api_error(&sv,"YouTube Search API не выполнил поиск"))}let mut ids=sv.get("items").and_then(|x|x.as_array()).cloned().unwrap_or_default().into_iter().filter_map(|x|x.pointer("/id/channelId").and_then(|v|v.as_str()).map(str::to_string)).filter(|x|x!=own_id).collect::<Vec<_>>();ids.sort();ids.dedup();if ids.is_empty(){return Ok(json!([]))}let joined=ids.join(",");let rr=client.get("https://www.googleapis.com/youtube/v3/channels").bearer_auth(&token).query(&[("part","snippet,statistics"),("id",joined.as_str())]).send().await.map_err(|e|format!("Competitor details: {e}"))?;let rv:Value=rr.json().await.unwrap_or_else(|_|json!({}));let mut out=Vec::<Value>::new();for item in rv.get("items").and_then(|x|x.as_array()).cloned().unwrap_or_default(){let id=item.get("id").and_then(|x|x.as_str()).unwrap_or("");if id.is_empty()||id==own_id{continue}let sn=item.get("snippet").cloned().unwrap_or_else(||json!({}));let stat=item.get("statistics").cloned().unwrap_or_else(||json!({}));let text=format!("{} {}",sn.get("title").and_then(|x|x.as_str()).unwrap_or(""),sn.get("description").and_then(|x|x.as_str()).unwrap_or(""));let mut similarity=overlap_score(&own_keys,&text);if similarity<15{similarity=15}let num=|k:&str|stat.get(k).and_then(|x|x.as_str()).and_then(|x|x.parse::<u64>().ok()).unwrap_or(0);out.push(json!({"channelId":id,"name":sn.get("title").and_then(|x|x.as_str()).unwrap_or("YouTube"),"url":format!("https://www.youtube.com/channel/{id}"),"thumbnail":thumb_url(&sn),"subscribers":num("subscriberCount"),"views":num("viewCount"),"videos":num("videoCount"),"similarity":similarity}))}out.sort_by(|a,b|b.get("similarity").and_then(|x|x.as_u64()).cmp(&a.get("similarity").and_then(|x|x.as_u64())));out.truncate(max as usize);Ok(json!(out))}
'''
